package com.garagedesk.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="bills") public class Bill { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @OneToOne(optional=false) @JoinColumn(name="job_card_id",unique=true) JobCard jobCard; double partsAmount; double labourCharge; double totalAmount; LocalDateTime generatedAt; public Bill(){} public Bill(JobCard j,double p,double l){jobCard=j;partsAmount=p;labourCharge=l;totalAmount=p+l;generatedAt=LocalDateTime.now();} public Long getId(){return id;} public JobCard getJobCard(){return jobCard;} public void setJobCard(JobCard v){jobCard=v;} public double getPartsAmount(){return partsAmount;} public void setPartsAmount(double v){partsAmount=v;} public double getLabourCharge(){return labourCharge;} public void setLabourCharge(double v){labourCharge=v;} public double getTotalAmount(){return totalAmount;} public void setTotalAmount(double v){totalAmount=v;} public LocalDateTime getGeneratedAt(){return generatedAt;} public void setGeneratedAt(LocalDateTime v){generatedAt=v;} @PrePersist @PreUpdate public void calc(){totalAmount=partsAmount+labourCharge;if(generatedAt==null)generatedAt=LocalDateTime.now();} }
